    74→/// Find a package's directory - tries as path first, then searches standard locations
    75→pub fn find_package_dir(workspace: &Path, name: &str) -> Result<PathBuf> {
    76→    // Try as path first (relative or absolute)
    77→    let as_path = PathBuf::from(name);
    78→    if as_path.join("Cargo.toml").exists() {
    79→        return Ok(as_path.canonicalize().unwrap_or(as_path));
    80→    }
    81→
    82→    // Fallback: search libs/, apps/, tools/
    83→    for prefix in ["libs", "apps", "tools"] {
    84→        let path = workspace.join(prefix).join(name);
    85→        if path.join("Cargo.toml").exists() {
    86→            return Ok(path);
    87→        }
    88→    }
    89→
    90→    // Special case: nested test crates like libs/rlibc-x2/tests
    91→    for prefix in ["libs", "apps"] {
    92→        for entry in std::fs::read_dir(workspace.join(prefix))
    93→            .into_iter()
    94→            .flatten()
    95→            .flatten()
    96→        {
    97→            let nested = entry.path().join("tests");
    98→            if nested.join("Cargo.toml").exists()
    99→                && let Ok(pkg_name) = get_crate_name(&nested)
   100→                && pkg_name == name

